# Analyst translations of the automatic caption tracks.
# English is a translation, not a Roman transliteration.
# Unclear ASR is marked in square brackets. Nothing is filled in from outside knowledge.

def C(primary, secondary, topic, subtopics, purpose, message, tone, structure, hook, takeaway, cta, entities, rationale, confidence="medium"):
    return {
        "primary": primary,
        "secondary": secondary,
        "main_topic": topic,
        "subtopics": subtopics,
        "intended_audience": "UPSC aspirants, inferred from the channel and the speech",
        "purpose": purpose,
        "core_message": message,
        "emotional_tone": tone,
        "narrative_structure": structure,
        "hook": hook,
        "takeaway": takeaway,
        "call_to_action": cta,
        "entities": entities,
        "rationale": rationale,
        "confidence": confidence,
    }

